<?php
require 'page-guard.php';require '../config/db_conn.php';require '../includes/attendance-schema.php';require '../includes/teacher-profile-schema.php';require '../includes/teacher-assignment-schema.php';ensureAttendanceTimeOutColumn($conn);ensureTeacherProfileColumns($conn);ensureTeacherAssignmentSchema($conn);
$section=trim($_GET['section']??'all');$grade=(int)($_GET['grade']??0);$date=$_GET['date']??date('Y-m-d');$student=trim($_GET['student']??'');$teacherId=(int)($_SESSION['teacher-id']??0);if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date)){http_response_code(400);exit('Invalid date.');}
$stmt=$conn->prepare("SELECT a.STUDENT_ID,COALESCE(s.STUDENT_NAME,a.STUDENT_NAME) STUDENT_NAME,s.GRADE,s.SECTION,a.TIME_IN,a.TIME_OUT FROM attendance a INNER JOIN students s ON TRIM(a.STUDENT_ID)=TRIM(s.STUDENT_ID) INNER JOIN (SELECT DISTINCT GRADE FROM teacher_assignments WHERE TEACHER_ID=?) ta ON ta.GRADE=s.GRADE WHERE DATE(a.TIME_IN)=? AND (?='all' OR s.SECTION=?) AND (?=0 OR s.GRADE=?) AND (?='' OR a.STUDENT_ID=?) ORDER BY s.GRADE,s.SECTION,STUDENT_NAME");$stmt->bind_param('isssiiss',$teacherId,$date,$section,$section,$grade,$grade,$student,$student);$stmt->execute();$result=$stmt->get_result();
if($result->num_rows):while($row=$result->fetch_assoc()):$timeIn=new DateTime($row['TIME_IN']);$timeOut=empty($row['TIME_OUT'])?null:new DateTime($row['TIME_OUT']);?><tr><td class="px-4 py-4"><?= htmlspecialchars($row['STUDENT_ID']) ?></td><td class="px-4 py-4 font-bold"><?= htmlspecialchars($row['STUDENT_NAME']) ?></td><td class="px-4 py-4"><span class="rounded-full bg-violet-50 px-3 py-1 text-xs font-bold text-violet-700">Grade <?= htmlspecialchars($row['GRADE']??'—') ?></span></td><td class="px-4 py-4"><a class="rounded-full bg-blue-50 px-3 py-1 text-xs font-bold text-blue-700 hover:bg-blue-100" href="students.php?grade=<?= (int)$row['GRADE'] ?>&section=<?= urlencode($row['SECTION']) ?>"><?= htmlspecialchars($row['SECTION']) ?></a></td><td class="px-4 py-4"><?= $timeIn->format('F j, Y') ?></td><td class="px-4 py-4"><?= $timeIn->format('g:i A') ?></td><td class="px-4 py-4"><?= $timeOut?$timeOut->format('g:i A'):'—' ?></td><td class="px-4 py-4"><?php if($timeOut): ?><span class="rounded-full bg-amber-50 px-3 py-1 text-xs font-bold text-amber-700">Dismissed</span><?php else: ?><span class="rounded-full bg-emerald-50 px-3 py-1 text-xs font-bold text-emerald-700">Present</span><?php endif; ?></td></tr><?php endwhile;else:?><tr><td colspan="8" class="px-4 py-10 text-center text-slate-500">No attendance records found.</td></tr><?php endif; ?>
